<script setup lang="ts">
import { computed, ref, watch, onUnmounted } from "vue";
import { request, item, query, privateFile, type TopupPaymentInstruction, type Topup, type PaymentReceipt, type Page } from "@papilio/api";
import { faNumber, faDate, faDigits } from "@papilio/ui";
import PaymentAmountDetails from "./payments/PaymentAmountDetails.vue";
const props=defineProps<{ topupId:number; audience:"admin"|"customer"; pending:boolean; canUpload:boolean; topup?:Topup }>();
const instruction=ref<TopupPaymentInstruction|null>(null); const payment=ref<Topup|null>(null); const rows=ref<PaymentReceipt[]>([]); const page=ref(1); const pages=ref(1); const state=ref<"loading"|"ready"|"error">("loading"); const error=ref(""); const busy=ref(false); const selectedFile=ref<File|null>(null); const input=ref<HTMLInputElement|null>(null); const preview=ref(""); const notice=ref(""); let version=0;
const amountDetails=computed(()=>payment.value?{payableAmountRial:payment.value.amount_rial,requestedAmountRial:instruction.value?.requested_amount_rial??payment.value.requested_amount_rial,identifierMode:instruction.value?.payment_identifier_mode??payment.value.payment_identifier_mode,code4:instruction.value?.payment_identifier_code4??payment.value.payment_identifier_code4}:null);
const path=()=>`${props.audience==='admin'?'/v1/admin/payments':'/v1/customer'}/topups/${props.topupId}`;
function clearPreview():void { if(preview.value) URL.revokeObjectURL(preview.value); preview.value=""; }
async function load():Promise<void> { const stamp=++version; state.value="loading"; error.value=""; try { const [instructions,receipts,topup]=await Promise.all([request<{data:TopupPaymentInstruction[]}>(path()+"/instruction"),request<Page<PaymentReceipt>>(path()+`/receipts?${query({page:page.value})}`),props.topup?Promise.resolve(props.topup):item<Topup>(path())]); if(stamp!==version)return; if(topup.id!==props.topupId)throw new Error("Payment details do not match the selected request."); const captured=instructions.data[0]??null; if(captured?.topup_id!=null&&(captured.topup_id!==topup.id||captured.payable_amount_rial!==topup.amount_rial))throw new Error("Captured payment instructions do not match this payment. Refresh before transferring."); payment.value=topup; instruction.value=captured; rows.value=receipts.data; pages.value=receipts.meta.pager?.total_pages??1; state.value="ready"; } catch(cause) { if(stamp===version) { state.value="error"; error.value=cause instanceof Error?cause.message:"The operation failed. Please try again."; } } }
async function view(row:PaymentReceipt):Promise<void> { const stamp=version; try { const image=await privateFile(path()+`/receipts/${row.id}`); if(stamp!==version)return; clearPreview(); preview.value=URL.createObjectURL(image); } catch(cause){ error.value=cause instanceof Error?cause.message:"The operation failed. Please try again."; } }
async function upload():Promise<void> { if(!selectedFile.value)return; const stamp=version; busy.value=true; error.value=""; notice.value=""; const data=new FormData(); data.set("file",selectedFile.value); try { await item<PaymentReceipt>(path()+"/receipts","POST",data); if(stamp!==version)return; selectedFile.value=null; if(input.value)input.value.value=""; notice.value="Receipt saved. Payment settlement still requires confirmation."; page.value=1; await load(); } catch(cause){if(stamp===version)error.value=cause instanceof Error?cause.message:"The operation failed. Please try again.";} finally {busy.value=false;} }
watch(()=>[props.topupId,props.audience,props.topup],()=>{clearPreview();selectedFile.value=null;if(input.value)input.value.value="";page.value=1;instruction.value=null;payment.value=props.topup??null;rows.value=[];notice.value="";void load();},{immediate:true}); onUnmounted(()=>{version++;clearPreview();});
</script>
<template><section class="form-grid"><h3>Payment instructions and receipts {{ faNumber(topupId) }}</h3><p v-if="error" class="message error" role="alert">{{ error }} <button class="btn small secondary" @click="load">Retry</button></p><p v-if="notice" role="status">{{ notice }}</p><p v-if="state==='loading'">Loading evidence…</p><PaymentAmountDetails v-if="amountDetails" v-bind="amountDetails" /><template v-if="instruction"><strong>{{ instruction.title }} · {{ instruction.bank_name }}</strong><p>{{ instruction.recipient }}</p><p class="tabular" dir="ltr">{{ faDigits(instruction.account) }}</p><p>{{ instruction.instructions }}</p></template><p v-else-if="state==='ready'">No destination was recorded for this request. Check the payment instructions.</p><p>A receipt image does not confirm settlement. Review the bank credit before manual approval.</p><div v-for="row in rows" :key="row.id" class="detail-line"><span>Receipt {{ faNumber(row.id) }} · {{ faDate(row.created_at) }} · {{ faNumber(row.size_bytes) }} bytes</span><button class="btn small secondary" @click="view(row)">View receipt</button></div><p v-if="state==='ready' && !rows.length">No receipts uploaded.</p><div class="pager"><button :disabled="page<=1" @click="page--; load()">‹</button><span>{{ faNumber(page) }}</span><button :disabled="page>=pages" @click="page++; load()">›</button></div><img v-if="preview" :src="preview" alt="Private payment receipt" style="max-width:100%;max-height:600px;object-fit:contain" /><form v-if="pending && canUpload" class="form-grid" @submit.prevent="upload"><label class="field"><span>Receipt image</span><input ref="input" type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="selectedFile=($event.target as HTMLInputElement).files?.[0]??null" /></label><button class="btn" :disabled="busy || !selectedFile">Receipt uploads</button></form></section></template>
